4	/// Empty env: no variable is ever set. Used by tests that only
5	/// exercise the literal-passthrough or escape paths.
6	struct NoEnv;
7	impl EnvVar for NoEnv {
8	    fn var(_: &str) -> Option<String> {
9	        None
10	    }
11	}
12	
13	/// Run [`env_replace_lossy`] and assert no placeholder went unresolved.
14	/// Used by tests that exercise paths where every placeholder must expand.
15	fn replace_clean<Sys: EnvVar>(text: &str) -> String {
16	    let (value, unresolved) = env_replace_lossy::<Sys>(text);
17	    assert_eq!(unresolved, Vec::<String>::new(), "unexpected unresolved placeholders");
18	    value
19	}
