21	#[test]
22	fn substitutes_simple_placeholder() {
23	    struct EnvWithToken;
24	    impl EnvVar for EnvWithToken {
25	        fn var(name: &str) -> Option<String> {
26	            (name == "TOKEN").then(|| "abc123".to_owned())
27	        }
28	    }
29	    assert_eq!(replace_clean::<EnvWithToken>("Bearer ${TOKEN}"), "Bearer abc123");
30	}
