133	/// The source-backslash count must come from the original input,
134	/// not from the working `output` buffer. Without that, a
135	/// previously-expanded variable whose value ends in `\` would be
136	/// conflated with literal source `\` characters preceding the
137	/// next `${...}`. Upstream's regex `(?<!\\)(\\*)\$\{...}` runs on
138	/// the source, so a single literal `\` between two placeholders
139	/// must escape only the second one regardless of any trailing `\`
140	/// in the first's value. Without the fix, env A=`x\` + source
141	/// `${A}\${B}` returned `x\` + B's value (B unescaped); upstream
142	/// returns `x\${B}` (B kept literal).
143	#[test]
144	fn backslash_count_uses_source_not_output_buffer() {
145	    struct Env;
146	    impl EnvVar for Env {
147	        fn var(name: &str) -> Option<String> {
148	            match name {
149	                "A" => Some(r"x\".to_owned()),
150	                "B" => Some("should-not-expand".to_owned()),
151	                _ => None,
152	            }
153	        }
154	    }
155	    // Single literal `\` between `${A}` and `${B}`. Must escape `${B}`.
156	    assert_eq!(replace_clean::<Env>(r"${A}\${B}"), r"x\${B}");
157	}
